//! The six regular convex polychora `{3,3,3}, {4,3,3}, {3,3,4}, {3,4,3}, {5,3,3}, {3,3,5}` as cell
//! decompositions of S³ ⊂ R⁴, generated by the reflection group `[p,q,r]` and projected to R³
//! stereographically from a pole that is not a vertex.

use super::coxeter_gram::{classify_schlafli, CoxeterRealisation, HoneycombRegime, Vec4};
use super::coxeter_orbit::{build_orbit_complex, OrbitOptions};
use super::CellComplex3d;

pub fn polychoron_name(p: u32, q: u32, r: u32) -> &'static str {
    match (p, q, r) {
        (3, 3, 3) => "5-cell {3,3,3}",
        (4, 3, 3) => "8-cell (tesseract) {4,3,3}",
        (3, 3, 4) => "16-cell {3,3,4}",
        (3, 4, 3) => "24-cell {3,4,3}",
        (5, 3, 3) => "120-cell {5,3,3}",
        (3, 3, 5) => "600-cell {3,3,5}",
        _ => "not a regular polychoron",
    }
}

fn dot4(a: &Vec4, b: &Vec4) -> f64 {
    (0..4).map(|i| a[i] * b[i]).sum()
}

fn unit4(a: Vec4) -> Vec4 {
    let n = dot4(&a, &a).sqrt();
    a.map(|x| x / n)
}

/// Orthonormal basis of the hyperplane orthogonal to `pole` (Gram–Schmidt on the coordinate axes).
fn complement_basis(pole: &Vec4) -> [Vec4; 3] {
    let mut basis: Vec<Vec4> = Vec::new();
    for e in super::coxeter_gram::identity4() {
        let mut v = e;
        for b in std::iter::once(pole).chain(basis.iter()) {
            let d = dot4(&v, b);
            for k in 0..4 {
                v[k] -= d * b[k];
            }
        }
        if dot4(&v, &v) > 1e-6 {
            basis.push(unit4(v));
        }
        if basis.len() == 3 {
            break;
        }
    }
    [basis[0], basis[1], basis[2]]
}

/// Stereographic projection of unit vectors from `pole`: `x ↦ (x·e_i) / (1 - x·pole)`.
pub fn stereographic(coords: &[Vec4], pole: &Vec4) -> Vec<[f64; 3]> {
    let basis = complement_basis(pole);
    coords
        .iter()
        .map(|x| {
            let den = 1.0 - dot4(x, pole);
            [dot4(x, &basis[0]) / den, dot4(x, &basis[1]) / den, dot4(x, &basis[2]) / den]
        })
        .collect()
}

/// Build the full polychoron `{p,q,r}` (refuses symbols that are not one of the six).
pub fn build_polychoron(p: u32, q: u32, r: u32) -> Result<CellComplex3d, String> {
    let cls = classify_schlafli(p, q, r);
    if cls.regime != HoneycombRegime::SphericalS3 {
        return Err(format!("{{{p},{q},{r}}} is not a regular polychoron of S³: {}", cls.reason));
    }
    let real = CoxeterRealisation::new(p, q, r)?;
    let opts = OrbitOptions { shells: u32::MAX, patch_layers: 0, infinite_cells: false, ideal_vertices: false };
    let mut cx = build_orbit_complex(&real, p, &opts, polychoron_name(p, q, r), "SphericalS3")?;
    // Pole: antipode of the central cell centre unless that is a vertex (5-cell), else of a face centre, ...
    let candidates = [real.w[3], real.w[2], real.w[1], [0.3, -0.5, 0.7, 0.4]].map(|w| unit4(w.map(|x| -x)));
    let pole = candidates
        .into_iter()
        .find(|c| cx.coords4.iter().all(|v| dot4(v, c) < 1.0 - 1e-3))
        .ok_or("no admissible stereographic pole")?;
    cx.points = stereographic(&cx.coords4, &pole);
    Ok(cx)
}
